def compute_median(sorted_data, stride, n):
    if not isinstance(sorted_data, (list, np.ndarray)):
        raise TypeError("Input data must be a list or numpy array.")
    if not all(isinstance(x, (int, float)) for x in sorted_data):
        raise ValueError("All elements in the data must be numeric.")
    if n <= 0:
        raise ValueError("Number of elements must be positive.")
    if stride <= 0:
        raise ValueError("Stride must be positive.")

    try:
        libgslcblas = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
        libgsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
    except OSError as e:
        raise RuntimeError(f"Failed to load GSL libraries: {e}")

    data = np.array(sorted_data, dtype=np.float64)
    data_ptr = data.ctypes.data_as(ctypes.POINTER(ctypes.c_double))

    median = gsl_stats_median_from_sorted_data(data_ptr, ctypes.c_int(stride), ctypes.c_int(n))
    return float(median)

