    gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
    gsl.gsl_matrix_memcpy.argtypes = [ctypes.POINTER(ctypes.c_void_p), ctypes.POINTER(ctypes.c_void_p)]
    gsl.gsl_matrix_memcpy.restype = ctypes.c_int

    if dest.size != src.size:
        return -1

    result = gsl.gsl_matrix_memcpy(dest.data, src.data)
    return result

def create_gsl_matrix(np_array):
    matrix = GSLMatrix(np_array)
    return matrix

