import ctypes
import sys

def load_gsl_libraries():
    try:
        ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
        gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
        return gsl
    except OSError as e:
        print(f"Error loading GSL libraries: {e}")
        sys.exit(1)

def gsl_cdf_beta_Pinv(gsl, P, a, b):
    # Define function signature
    gsl.gsl_cdf_beta_Pinv.argtypes = [ctypes.c_double, ctypes.c_double, ctypes.c_double, ctypes.POINTER(ctypes.c_double)]
