def wrap_func(func):
    class WrappedFunc(ctypes.CFUNCTYPE):
        _restype = ctypes.c_double
        _argtypes_ = [ctypes.c_double, ctypes.c_void_p]

        def __init__(self, func):
            super().__init__(func)

        def __call__(self, x, params):
            return self.func(x)

    return WrappedFunc(func)

