        self.size = size
        self.vector = gsl.gsl_vector_alloc(ctypes.c_size_t(size))

    def set(self, index, value):
        gsl.gsl_vector_set(self.vector, ctypes.c_size_t(index), ctypes.c_double(value))

    def get(self, index):
        return gsl.gsl_vector_get(self.vector, ctypes.c_size_t(index))

    def free(self):
