import numpy as np

class GSLMatrix:
    def __init__(self, data):
        self.data = data
        self.size = len(data)
        self.n = self.size
        self.m = self.size
        self.storage = (ctypes.c_double * (self.n * self.m))(*np.array(data, dtype=np.float64).flatten())
        self.ptr = ctypes.pointer(self.storage)

    def to_list(self):
        return np.array(self.storage, dtype=np.float64).reshape(self.n, self.m).tolist()

