    def __init__(self, data):
        self.data = data
        self.n = len(data)
        self.m = len(data[0]) if self.n > 0 else 0
        self.spmatrix = None

    def __del__(self):
        if self.spmatrix:
            self.spmatrix.contents.data = None
            self.spmatrix = None

    @classmethod
def create_gsl_spmatrix(cls):
    ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
    gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

    gsl.gsl_spmatrix_alloc.restype = ctypes.POINTER(ctypes.c_void_p)
    gsl.gsl_spmatrix_alloc.argtypes = [ctypes.c_int, ctypes.c_int, ctypes.c_int]

    spmatrix = gsl.gsl_spmatrix_alloc(ctypes.c_int(cls.n), ctypes.c_int(cls.m), ctypes.c_int(0))
    if not spmatrix:
        raise RuntimeError("Failed to allocate sparse matrix")

    for i in range(cls.n):
        for j in range(cls.m):
            gsl.gsl_spmatrix_set(spmatrix, ctypes.c_int(i), ctypes.c_int(j), ctypes.c_double(cls.data[i][j]))

    return GSLSpMatrix(spmatrix)

    def perform_matrix_operation(self):
        gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

        gsl.gsl_spmatrix_scale.restype = None
        gsl.gsl_spmatrix_scale.argtypes = [ctypes.POINTER(ctypes.c_void_p), ctypes.c_double]

        gsl.gsl_spmatrix_scale(self.spmatrix, ctypes.c_double(2.0))

        result = [[0.0 for _ in range(self.m)] for _ in range(self.n)]
        for i in range(self.n):
            for j in range(self.m):
                result[i][j] = ctypes.c_double(self.data[i][j]).value * 2.0

        return result

