class GSLMatrix:
    def __init__(self, size):
        self.size = size
        self.data = np.zeros(size * size, dtype=np.float64)
        self._matrix = None

    def __del__(self):
        if self._matrix:
            ctypes.c_void_p(self._matrix).value = 0

    def _create_gsl_matrix(self):
        libgslcblas = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
        libgsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

        libgsl.gsl_matrix_alloc.argtypes = [ctypes.c_int, ctypes.c_int]
        libgsl.gsl_matrix_alloc.restype = ctypes.c_void_p

        self._matrix = libgsl.gsl_matrix_alloc(ctypes.c_int(self.size), ctypes.c_int(self.size))

    def _free_gsl_matrix(self):
        if self._matrix:
            libgsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
            libgsl.gsl_matrix_free.argtypes = [ctypes.c_void_p]
            libgsl.gsl_matrix_free(ctypes.c_void_p(self._matrix))
            self._matrix = None

    def _copy_data_to_gsl(self, matrix):
        if self._matrix is None:
            self._create_gsl_matrix()

        for i in range(self.size):
            for j in range(self.size):
                ctypes.c_double(matrix[i][j]).value = ctypes.c_double(self.data[i * self.size + j])
                ctypes.c_double(self.data[i * self.size + j]).value = matrix[i][j]

    def _copy_data_from_gsl(self):
        if self._matrix is None:
            self._create_gsl_matrix()

        for i in range(self.size):
            for j in range(self.size):
                self.data[i * self.size + j] = ctypes.c_double(ctypes.c_double(self.data[i * self.size + j]).value).value

    def _get_gsl_matrix(self):
        if self._matrix is None:
            self._create_gsl_matrix()
        return self._matrix

    def _set_data(self, matrix):
        self.data = np.array(matrix, dtype=np.float64).flatten()

    def _get_data(self):
        return self.data.reshape(self.size, self.size)

    data = property(_get_data, _set_data)


def matrix_to_gsl(matrix):
    size = len(matrix)
    gsl_matrix = GSLMatrix(size)
    gsl_matrix.data = np.array(matrix, dtype=np.float64).flatten()
    return gsl_matrix

def gsl_matrix_to_numpy(gsl_matrix):
    gsl_matrix._copy_data_from_gsl()
    return gsl_matrix.data.reshape(gsl_matrix.size, gsl_matrix.size)

def compute_matrix_exponential(matrix, mode):
    try:
        size = len(matrix)
        if not all(len(row) == size for row in matrix):
