        self._data = self.data.ctypes.data_as(ctypes.POINTER(ctypes.c_double))

    @property
    def data(self):
        return self._data

    def set_data(self, data):
        self._data = np.array(data, dtype=np.float64).ctypes.data_as(ctypes.POINTER(ctypes.c_double))

    def get_data(self):
        return np.ctypeslib.as_array(self._data, shape=(self.size, self.size)).copy()


def matrix_to_gsl(matrix):
    size = len(matrix)
    gsl_matrix = GSLMatrix(size)
    gsl_matrix.set_data(matrix)
    return gsl_matrix

