        gsl.gsl_linalg_exponential_ss.restype = None

        exp_matrix = GSLMatrix(size)
        exp_matrix_data = exp_matrix.data

        gsl.gsl_linalg_exponential_ss(gsl_matrix_data, size, exp_matrix_data, mode)

        return gsl_matrix_to_numpy(exp_matrix)
    except Exception as e:
