def main(N, K, t):
    workspace = GSLFilterImpulseWorkspace(K)
    signal = np.random.normal(0, 1, N)
    signal += np.random.normal(0, 0.5, N)
    signal += np.random.choice([-5, 5], size=N, p=[0.01, 0.01])
    vec = GSLVector(N)
