def cholesky_decomposition(input_matrix):
    n = len(input_matrix)
    matrix = gsl_matrix_alloc(n, n)
    perm = gsl_permutation_alloc(n)

    for i in range(n):
        for j in range(n):
            gsl_matrix_set(matrix, i, j, input_matrix[i][j])

    status = gsl.gsl_linalg_pcholesky_decomp(matrix, perm)

    if status != 0:
        raise ValueError("Cholesky decomposition failed")

    # Extract results
    result_matrix = [[gsl_matrix_get(matrix, i, j) for j in range(n)] for i in range(n)]
    result_perm = [gsl_permutation_get(perm, i) for i in range(n)]

    # Free memory
    gsl.gsl_matrix_free(matrix)
    gsl.gsl_permutation_free(perm)

    return result_matrix, result_perm

