    def __del__(self):
        free_gsl_matrix(self.matrix)

    @staticmethod
    def create_gsl_matrix(data):
        rows = len(data)
        cols = len(data[0]) if rows > 0 else 0
        matrix = GSLMatrix(rows, cols)
        matrix.matrix = ctypes.c_void_p()

        # Convert numpy array to GSL matrix
        matrix.matrix = gsl.gsl_matrix_alloc(rows, cols)
        for i in range(rows):
            for j in range(cols):
                gsl.gsl_matrix_set(matrix.matrix, i, j, data[i][j])
        return matrix

    @staticmethod
    def retrieve_gsl_matrix(matrix):
        data = np.zeros((matrix.rows, matrix.cols), dtype=np.float64)
        for i in range(matrix.rows):
            for j in range(matrix.cols):
                data[i][j] = gsl.gsl_matrix_get(matrix.matrix, i, j)
        return data.tolist()

    @staticmethod
    def free_gsl_matrix(matrix):
        gsl.gsl_matrix_free(matrix)

