            gsl.gsl_linalg_cholesky_decomp.restype = ctypes.c_int

            status = gsl.gsl_linalg_cholesky_decomp(self.pointer, n)
            if status != 0:
                raise ValueError("Cholesky decomposition failed")

            L = np.zeros((n, n))
            for i in range(n):
