class GSLHistogram2D:
    def __init__(self, nx, ny, xrange, yrange):
        self.nx = nx
        self.ny = ny
        self.xrange = xrange
        self.yrange = yrange
        self.data = np.zeros((nx, ny), dtype=np.int32)

    def increment(self, x, y):
        self.data[self._find_bin(x, self.xrange), self._find_bin(y, self.yrange)] += 1

